create extension if not exists pgcrypto;
create or replace function public.normalize_trial_email(raw_email text) returns text language plpgsql immutable as $$ declare local_part text;domain_part text;begin local_part:=split_part(lower(trim(raw_email)),'@',1);domain_part:=split_part(lower(trim(raw_email)),'@',2);local_part:=split_part(local_part,'+',1);if domain_part in('gmail.com','googlemail.com') then local_part:=replace(local_part,'.','');domain_part:='gmail.com';end if;return local_part||'@'||domain_part;end $$;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,name text,phone text,trial_start_date timestamptz,trial_end_date timestamptz,plan_type text not null default 'none' check(plan_type in('trial','subscription','credits','none')),created_at timestamptz not null default now());
create table if not exists public.trial_records (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),email_normalized text not null,device_fingerprint_hash text,ip_fingerprint_hash text,trial_start_date timestamptz not null,trial_end_date timestamptz not null,created_at timestamptz not null default now());
create unique index if not exists one_trial_per_normalized_email on public.trial_records(email_normalized);
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade,email text unique not null);
create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),plan_type text not null default 'monthly',start_date timestamptz not null,end_date timestamptz not null,status text not null default 'active' check(status in('active','expired')));
create table if not exists public.credits (user_id uuid primary key references auth.users(id),balance integer not null default 0 check(balance>=0),last_updated timestamptz not null default now());
create table if not exists public.payment_submissions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount numeric(10,2) not null,plan_type text not null check(plan_type in('subscription','credits')),payment_method text not null default 'bank' check(payment_method in('bank','ewallet')),receipt_image_path text not null,status text not null default 'pending' check(status in('pending','approved','rejected')),submitted_at timestamptz not null default now(),reviewed_at timestamptz,reviewed_by uuid references auth.users(id));
alter table public.payment_submissions add column if not exists payment_method text not null default 'bank' check(payment_method in('bank','ewallet'));
create table if not exists public.generations (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),tool_used text not null,access_type text not null,created_at timestamptz not null default now());
alter table profiles enable row level security;alter table trial_records enable row level security;alter table subscriptions enable row level security;alter table credits enable row level security;alter table payment_submissions enable row level security;alter table generations enable row level security;alter table admin_users enable row level security;
create or replace function public.is_admin() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from admin_users where user_id=auth.uid()) $$;
create policy "read own admin status" on admin_users for select using(user_id=auth.uid());create policy "read own profile" on profiles for select using(auth.uid()=id);create policy "update own profile" on profiles for update using(auth.uid()=id);create policy "read own subscription" on subscriptions for select using(auth.uid()=user_id);create policy "read own credits" on credits for select using(auth.uid()=user_id);create policy "submit own payment" on payment_submissions for insert with check(auth.uid()=user_id and status='pending');create policy "read own payments" on payment_submissions for select using(auth.uid()=user_id or is_admin());create policy "write own generation" on generations for insert with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public) values('payment-receipts','payment-receipts',false) on conflict do nothing;
create policy "upload own receipt" on storage.objects for insert to authenticated with check(bucket_id='payment-receipts' and(storage.foldername(name))[1]=auth.uid()::text);create policy "read receipt" on storage.objects for select to authenticated using(bucket_id='payment-receipts' and((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
create or replace function public.review_payment(submission_id uuid,new_status text) returns void language plpgsql security definer set search_path=public as $$ declare s payment_submissions;begin if not is_admin() then raise exception 'not authorized';end if;if new_status not in('approved','rejected') then raise exception 'invalid status';end if;select * into s from payment_submissions where id=submission_id and status='pending' for update;if not found then raise exception 'submission not pending';end if;update payment_submissions set status=new_status,reviewed_at=now(),reviewed_by=auth.uid() where id=submission_id;if new_status='approved' and s.plan_type='credits' then insert into credits(user_id,balance) values(s.user_id,5) on conflict(user_id) do update set balance=credits.balance+5,last_updated=now();update profiles set plan_type='credits' where id=s.user_id;end if;if new_status='approved' and s.plan_type='subscription' then insert into subscriptions(user_id,start_date,end_date) values(s.user_id,now(),now()+interval '30 days');update profiles set plan_type='subscription' where id=s.user_id;end if;end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,name,trial_start_date,trial_end_date,plan_type) values(new.id,new.raw_user_meta_data->>'name',case when new.email_confirmed_at is not null then now() end,case when new.email_confirmed_at is not null then now()+interval '7 days' end,case when new.email_confirmed_at is not null then 'trial' else 'none' end);if new.email_confirmed_at is not null then insert into trial_records(user_id,email_normalized,trial_start_date,trial_end_date) values(new.id,normalize_trial_email(new.email),now(),now()+interval '7 days');end if;insert into credits(user_id,balance) values(new.id,0);return new;end $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.handle_email_confirmed() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.email_confirmed_at is null and new.email_confirmed_at is not null then insert into trial_records(user_id,email_normalized,trial_start_date,trial_end_date) values(new.id,normalize_trial_email(new.email),now(),now()+interval '7 days');update profiles set trial_start_date=now(),trial_end_date=now()+interval '7 days',plan_type='trial' where id=new.id;end if;return new;end $$;
drop trigger if exists on_auth_email_confirmed on auth.users;create trigger on_auth_email_confirmed after update of email_confirmed_at on auth.users for each row execute procedure public.handle_email_confirmed();
